const ZH3=[
["Family and people 2",[["姐姐","jiějie","older sister","我姐姐住在上海。","Wǒ jiějie zhù zài Shànghǎi.","My older sister lives in Shanghai."],["弟弟","dìdi","younger brother","我弟弟是学生。","Wǒ dìdi shì xuésheng.","My younger brother is a student."],["妹妹","mèimei","younger sister","我妹妹十岁。","Wǒ mèimei shí suì.","My younger sister is ten years old."],["孩子","háizi","child","他有两个孩子。","Tā yǒu liǎng ge háizi.","He has two children."],["丈夫","zhàngfu","husband","她丈夫是医生。","Tā zhàngfu shì yīshēng.","Her husband is a doctor."],["妻子","qīzi","wife","他妻子是老师。","Tā qīzi shì lǎoshī.","His wife is a teacher."],["男","nán","male, man","那个男人是我哥哥。","Nàge nánrén shì wǒ gēge.","That man is my older brother."],["女","nǚ","female, woman","那个女孩子很高。","Nàge nǚ háizi hěn gāo.","That girl is tall."],["大家","dàjiā","everyone","大家好！","Dàjiā hǎo!","Hello, everyone!"],["您","nín","you (polite)","您好，请进。","Nín hǎo, qǐng jìn.","Hello, please come in."]]],
["Everyday actions",[["洗","xǐ","to wash","我洗手。","Wǒ xǐ shǒu.","I wash my hands."],["穿","chuān","to wear, to put on","今天很冷，多穿衣服。","Jīntiān hěn lěng, duō chuān yīfu.","It is cold today. Wear more clothes."],["走","zǒu","to walk, to leave","我们走吧。","Wǒmen zǒu ba.","Let’s go."],["跑步","pǎobù","to jog, to run","我每天早上跑步。","Wǒ měitiān zǎoshang pǎobù.","I jog every morning."],["找","zhǎo","to look for","我在找我的手机。","Wǒ zài zhǎo wǒ de shǒujī.","I am looking for my phone."],["等","děng","to wait","请等一下。","Qǐng děng yíxià.","Please wait a moment."],["送","sòng","to give, to deliver, to see off","我送你回家。","Wǒ sòng nǐ huí jiā.","I will take you home."],["进","jìn","to enter","请进！","Qǐng jìn!","Please come in!"],["出","chū","to go out, to exit","他出去了。","Tā chūqu le.","He has gone out."],["完","wán","to finish","我吃完了。","Wǒ chī wán le.","I have finished eating."]]],
["Talking and knowing",[["告诉","gàosu","to tell","请告诉我你的名字。","Qǐng gàosu wǒ nǐ de míngzi.","Please tell me your name."],["问","wèn","to ask","我可以问你一个问题吗？","Wǒ kěyǐ wèn nǐ yí ge wèntí ma?","May I ask you a question?"],["回答","huídá","to answer","请回答我的问题。","Qǐng huídá wǒ de wèntí.","Please answer my question."],["问题","wèntí","question, problem","没有问题。","Méiyǒu wèntí.","No problem."],["知道","zhīdào","to know (a fact)","我不知道。","Wǒ bù zhīdào.","I do not know."],["懂","dǒng","to understand","你懂吗？","Nǐ dǒng ma?","Do you understand?"],["介绍","jièshào","to introduce","我介绍一下，这是我朋友。","Wǒ jièshào yíxià, zhè shì wǒ péngyou.","Let me introduce: this is my friend."],["意思","yìsi","meaning","这个字是什么意思？","Zhège zì shì shénme yìsi?","What does this character mean?"],["觉得","juéde","to feel, to think","我觉得很好。","Wǒ juéde hěn hǎo.","I think it is good."],["希望","xīwàng","to hope","我希望明天不下雨。","Wǒ xīwàng míngtiān bú xià yǔ.","I hope it does not rain tomorrow."]]],
["Time 2",[["小时","xiǎoshí","hour","我睡了八个小时。","Wǒ shuì le bā ge xiǎoshí.","I slept for eight hours."],["时间","shíjiān","time","你有时间吗？","Nǐ yǒu shíjiān ma?","Do you have time?"],["去年","qùnián","last year","去年我去了北京。","Qùnián wǒ qù le Běijīng.","Last year I went to Beijing."],["生日","shēngrì","birthday","今天是我的生日。","Jīntiān shì wǒ de shēngrì.","Today is my birthday."],["日","rì","day (of the month)","五月一日","Wǔyuè yī rì","1 May"],["每","měi","every","我每天喝茶。","Wǒ měitiān hē chá.","I drink tea every day."],["已经","yǐjīng","already","我已经吃饭了。","Wǒ yǐjīng chī fàn le.","I have already eaten."],["正在","zhèngzài","in the middle of (doing)","我正在上课。","Wǒ zhèngzài shàng kè.","I am in class right now."],["就","jiù","then, right away","我马上就来。","Wǒ mǎshàng jiù lái.","I am coming right away."],["再","zài","again","请再说一次。","Qǐng zài shuō yí cì.","Please say it again."]]],
["Food and drink 2",[["鸡蛋","jīdàn","egg","我早上吃鸡蛋。","Wǒ zǎoshang chī jīdàn.","I eat eggs in the morning."],["牛奶","niúnǎi","milk","我喝牛奶。","Wǒ hē niúnǎi.","I drink milk."],["面条","miàntiáo","noodles","我想吃面条。","Wǒ xiǎng chī miàntiáo.","I want to eat noodles."],["鱼","yú","fish","这条鱼很大。","Zhè tiáo yú hěn dà.","This fish is big."],["羊肉","yángròu","lamb","北京的羊肉很好吃。","Běijīng de yángròu hěn hǎochī.","The lamb in Beijing is tasty."],["西瓜","xīguā","watermelon","夏天吃西瓜。","Xiàtiān chī xīguā.","In summer we eat watermelon."],["咖啡","kāfēi","coffee","我要一杯咖啡。","Wǒ yào yì bēi kāfēi.","I want a cup of coffee."],["好吃","hǎochī","tasty (food)","这个菜很好吃。","Zhège cài hěn hǎochī.","This dish is tasty."],["饭店","fàndiàn","restaurant","我们去饭店吃饭吧。","Wǒmen qù fàndiàn chī fàn ba.","Let’s go to a restaurant to eat."],["水果","shuǐguǒ","fruit","我喜欢吃水果。","Wǒ xǐhuan chī shuǐguǒ.","I like eating fruit."]]],
["Travel 2",[["机场","jīchǎng","airport","我去机场。","Wǒ qù jīchǎng.","I am going to the airport."],["宾馆","bīnguǎn","hotel","这个宾馆很好。","Zhège bīnguǎn hěn hǎo.","This hotel is good."],["房间","fángjiān","room","我的房间在三楼。","Wǒ de fángjiān zài sān lóu.","My room is on the third floor."],["票","piào","ticket","我买了两张票。","Wǒ mǎi le liǎng zhāng piào.","I bought two tickets."],["公共汽车","gōnggòng qìchē","bus","我坐公共汽车去学校。","Wǒ zuò gōnggòng qìchē qù xuéxiào.","I take the bus to school."],["旅游","lǚyóu","to travel, tourism","我喜欢旅游。","Wǒ xǐhuan lǚyóu.","I like travelling."],["离","lí","away from (distance)","我家离学校很近。","Wǒ jiā lí xuéxiào hěn jìn.","My home is close to the school."],["往","wǎng","towards","往前走。","Wǎng qián zǒu.","Walk forward."],["门","mén","door, gate","请开门。","Qǐng kāi mén.","Please open the door."],["服务员","fúwùyuán","waiter, attendant","服务员，买单。","Fúwùyuán, mǎidān.","Waiter, the bill please."]]],
["Sport and fun",[["运动","yùndòng","sport, exercise","我每天运动。","Wǒ měitiān yùndòng.","I exercise every day."],["游泳","yóuyǒng","to swim","夏天我去游泳。","Xiàtiān wǒ qù yóuyǒng.","In summer I go swimming."],["踢足球","tī zúqiú","to play football","他们在踢足球。","Tāmen zài tī zúqiú.","They are playing football."],["打篮球","dǎ lánqiú","to play basketball","我喜欢打篮球。","Wǒ xǐhuan dǎ lánqiú.","I like playing basketball."],["唱歌","chànggē","to sing","她唱歌唱得很好。","Tā chànggē chàng de hěn hǎo.","She sings very well."],["跳舞","tiàowǔ","to dance","我们去跳舞吧。","Wǒmen qù tiàowǔ ba.","Let’s go dancing."],["玩","wán","to play, to have fun","周末我们去玩。","Zhōumò wǒmen qù wán.","At the weekend we go out to have fun."],["笑","xiào","to laugh, to smile","他笑了。","Tā xiào le.","He smiled."],["快乐","kuàilè","happy","生日快乐！","Shēngrì kuàilè!","Happy birthday!"],["比赛","bǐsài","match, competition","今天有足球比赛。","Jīntiān yǒu zúqiú bǐsài.","There is a football match today."]]],
["Shopping 2",[["卖","mài","to sell","这个商店卖水果。","Zhège shāngdiàn mài shuǐguǒ.","This shop sells fruit."],["贵","guì","expensive","这个太贵了。","Zhège tài guì le.","This is too expensive."],["便宜","piányi","cheap","这个很便宜。","Zhège hěn piányi.","This is cheap."],["件","jiàn","(measure word for clothes, matters)","我买了一件衣服。","Wǒ mǎi le yí jiàn yīfu.","I bought a piece of clothing."],["颜色","yánsè","colour","你喜欢什么颜色？","Nǐ xǐhuan shénme yánsè?","What colour do you like?"],["手表","shǒubiǎo","watch","这是我的新手表。","Zhè shì wǒ de xīn shǒubiǎo.","This is my new watch."],["手机","shǒujī","mobile phone","我的手机没电了。","Wǒ de shǒujī méi diàn le.","My phone has no battery."],["千","qiān","thousand","一千块","Yì qiān kuài","1,000 yuan"],["百","bǎi","hundred","一百块","Yì bǎi kuài","100 yuan"],["零","líng","zero","我的号码是零一三。","Wǒ de hàomǎ shì líng yāo sān.","My number is 0-1-3."]]],
["Describing 2",[["长","cháng","long","这条路很长。","Zhè tiáo lù hěn cháng.","This road is long."],["高","gāo","tall, high","我哥哥很高。","Wǒ gēge hěn gāo.","My older brother is tall."],["快","kuài","fast","他走得很快。","Tā zǒu de hěn kuài.","He walks fast."],["慢","màn","slow","请说慢一点。","Qǐng shuō màn yìdiǎn.","Please speak more slowly."],["忙","máng","busy","我今天很忙。","Wǒ jīntiān hěn máng.","I am busy today."],["真","zhēn","really","你的中文真好！","Nǐ de Zhōngwén zhēn hǎo!","Your Chinese is really good!"],["非常","fēicháng","extremely","今天非常热。","Jīntiān fēicháng rè.","Today is extremely hot."],["最","zuì","most","我最喜欢饺子。","Wǒ zuì xǐhuan jiǎozi.","I like dumplings the most."],["错","cuò","wrong","对不起，我错了。","Duìbuqǐ, wǒ cuò le.","Sorry, I was wrong."],["对","duì","right, correct","你说得对。","Nǐ shuō de duì.","You are right."]]],
["Weather and seasons 2",[["晴","qíng","sunny","今天是晴天。","Jīntiān shì qíngtiān.","Today is a sunny day."],["阴","yīn","overcast","明天阴天。","Míngtiān yīntiān.","Tomorrow will be overcast."],["刮风","guā fēng","to be windy","今天刮风。","Jīntiān guā fēng.","It is windy today."],["下雪","xià xuě","to snow","北京下雪了。","Běijīng xià xuě le.","It is snowing in Beijing."],["春天","chūntiān","spring","春天不冷也不热。","Chūntiān bù lěng yě bú rè.","Spring is neither cold nor hot."],["夏天","xiàtiān","summer","夏天很热。","Xiàtiān hěn rè.","Summer is hot."],["秋天","qiūtiān","autumn","我最喜欢秋天。","Wǒ zuì xǐhuan qiūtiān.","I like autumn the most."],["冬天","dōngtiān","winter","冬天很冷。","Dōngtiān hěn lěng.","Winter is cold."],["天","tiān","day, sky","我在北京住三天。","Wǒ zài Běijīng zhù sān tiān.","I stay in Beijing for three days."],["雨伞","yǔsǎn","umbrella","下雨了，带雨伞吧。","Xià yǔ le, dài yǔsǎn ba.","It is raining. Take an umbrella."]]],
["Work and school 2",[["上班","shàngbān","to go to work","我八点上班。","Wǒ bā diǎn shàngbān.","I start work at eight."],["公司","gōngsī","company","我在一家公司工作。","Wǒ zài yì jiā gōngsī gōngzuò.","I work at a company."],["教室","jiàoshì","classroom","我们在教室上课。","Wǒmen zài jiàoshì shàng kè.","We have class in the classroom."],["课","kè","class, lesson","今天有中文课。","Jīntiān yǒu Zhōngwén kè.","Today there is a Chinese class."],["考试","kǎoshì","exam","明天有考试。","Míngtiān yǒu kǎoshì.","There is an exam tomorrow."],["题","tí","question (in an exam)","这个题很难。","Zhège tí hěn nán.","This question is difficult."],["铅笔","qiānbǐ","pencil","我有一支铅笔。","Wǒ yǒu yì zhī qiānbǐ.","I have a pencil."],["报纸","bàozhǐ","newspaper","爸爸看报纸。","Bàba kàn bàozhǐ.","Dad reads the newspaper."],["开始","kāishǐ","to start","我们开始吧。","Wǒmen kāishǐ ba.","Let’s start."],["准备","zhǔnbèi","to prepare","我在准备考试。","Wǒ zài zhǔnbèi kǎoshì.","I am preparing for the exam."]]],
["The body",[["生病","shēngbìng","to get ill","我生病了。","Wǒ shēngbìng le.","I am ill."],["感冒","gǎnmào","a cold, to catch a cold","我感冒了。","Wǒ gǎnmào le.","I have a cold."],["发烧","fāshāo","to have a fever","你发烧吗？","Nǐ fāshāo ma?","Do you have a fever?"],["鼻子","bízi","nose","我的鼻子不舒服。","Wǒ de bízi bù shūfu.","My nose feels uncomfortable."],["嘴","zuǐ","mouth","请张开嘴。","Qǐng zhāngkāi zuǐ.","Please open your mouth."],["耳朵","ěrduo","ear","我的耳朵疼。","Wǒ de ěrduo téng.","My ear hurts."],["脚","jiǎo","foot","我的脚很累。","Wǒ de jiǎo hěn lèi.","My feet are tired."],["腿","tuǐ","leg","他的腿很长。","Tā de tuǐ hěn cháng.","His legs are long."],["胖","pàng","fat, plump","我的猫很胖。","Wǒ de māo hěn pàng.","My cat is plump."],["瘦","shòu","thin","她很瘦。","Tā hěn shòu.","She is thin."]]],
["Linking words",[["因为","yīnwèi","because","因为下雨，我不去。","Yīnwèi xià yǔ, wǒ bú qù.","Because it is raining, I am not going."],["所以","suǒyǐ","so, therefore","我很累，所以想休息。","Wǒ hěn lèi, suǒyǐ xiǎng xiūxi.","I am tired, so I want to rest."],["虽然","suīrán","although","虽然很贵，但是很好。","Suīrán hěn guì, dànshì hěn hǎo.","Although it is expensive, it is good."],["但是","dànshì","but","我想去，但是没有时间。","Wǒ xiǎng qù, dànshì méiyǒu shíjiān.","I want to go, but I have no time."],["还","hái","still, also","他还没来。","Tā hái méi lái.","He has still not come."],["也","yě","also","我也是学生。","Wǒ yě shì xuésheng.","I am also a student."],["别","bié","do not","别说话！","Bié shuōhuà!","Do not talk!"],["让","ràng","to let, to make (someone do)","妈妈让我早点回家。","Māma ràng wǒ zǎo diǎn huí jiā.","Mum tells me to come home early."],["要","yào","to want, to need, will","我要一杯水。","Wǒ yào yì bēi shuǐ.","I want a glass of water."],["可能","kěnéng","maybe, possible","明天可能下雨。","Míngtiān kěnéng xià yǔ.","It may rain tomorrow."]]],
["Small grammar words",[["可以","kěyǐ","may, can","我可以进来吗？","Wǒ kěyǐ jìnlái ma?","May I come in?"],["欢迎","huānyíng","welcome","欢迎来中国！","Huānyíng lái Zhōngguó!","Welcome to China!"],["帮助","bāngzhù","to help, help","谢谢你的帮助。","Xièxie nǐ de bāngzhù.","Thank you for your help."],["第一","dì yī","first","这是我第一次来北京。","Zhè shì wǒ dì yī cì lái Běijīng.","This is my first time in Beijing."],["次","cì","time(s), occurrence","我去过两次。","Wǒ qù guo liǎng cì.","I have been there twice."],["一下","yíxià","(do) briefly, a little","你看一下。","Nǐ kàn yíxià.","Have a look."],["着","zhe","(continuing state)","门开着。","Mén kāi zhe.","The door is open."],["过","guo","(past experience)","我吃过北京烤鸭。","Wǒ chī guo Běijīng kǎoyā.","I have eaten Beijing roast duck."],["得","de","(links a verb to how it is done)","他说得很好。","Tā shuō de hěn hǎo.","He speaks well."],["吧","ba","(suggestion)","我们走吧。","Wǒmen zǒu ba.","Let’s go."]]],
["Around the building",[["它","tā","it","这是我的猫，它很小。","Zhè shì wǒ de māo, tā hěn xiǎo.","This is my cat. It is small."],["灯","dēng","light, lamp","请开灯。","Qǐng kāi dēng.","Please turn on the light."],["冰箱","bīngxiāng","fridge","牛奶在冰箱里。","Niúnǎi zài bīngxiāng li.","The milk is in the fridge."],["空调","kōngtiáo","air conditioner","请开空调。","Qǐng kāi kōngtiáo.","Please turn on the air conditioner."],["洗手间","xǐshǒujiān","toilet, restroom","洗手间在哪儿？","Xǐshǒujiān zài nǎr?","Where is the toilet?"],["电梯","diàntī","lift, elevator","我们坐电梯吧。","Wǒmen zuò diàntī ba.","Let’s take the lift."],["楼","lóu","floor, building","我住在五楼。","Wǒ zhù zài wǔ lóu.","I live on the fifth floor."],["包","bāo","bag","我的包很重。","Wǒ de bāo hěn zhòng.","My bag is heavy."],["照片","zhàopiàn","photo","这是我家的照片。","Zhè shì wǒ jiā de zhàopiàn.","This is a photo of my family."],["地图","dìtú","map","我看一下地图。","Wǒ kàn yíxià dìtú.","Let me look at the map."]]]
];
